verify.program:
public class CountSymbols
{
    public static void main(String[] args)
    {
        String pwd = "pa ss@1";
        int symbols = 0;
        for(int i = 0; i < pwd.length(); ++i)
            if(!Character.isLetterOrDigit(pwd.charAt(i)))
                ++symbols;
        System.out.println(symbols);
    }
}

